import json
from pathlib import Path

from app.models.schemas import CaseRecord, ChatMessage, DoctorSummary, ReviewedFinding
from app.storage.interface import CaseStorage


class LocalFilesystemCaseStorage(CaseStorage):
    """storage/cases/{case_id}/ with original.<ext>, prediction.json, review.json"""

    def __init__(self, root: str | Path):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)

    def _case_dir(self, case_id: str) -> Path:
        # case_id is generated by us (uuid4 hex), never derived from user input,
        # so this cannot be used for path traversal.
        safe_id = "".join(c for c in case_id if c.isalnum() or c == "-")
        if safe_id != case_id:
            raise ValueError("invalid case_id")
        d = self.root / safe_id
        d.mkdir(parents=True, exist_ok=True)
        return d

    def save_original_image(self, case_id: str, image_bytes: bytes, extension: str) -> str:
        ext = extension if extension.startswith(".") else f".{extension}"
        allowed = {".jpg", ".jpeg", ".png"}
        if ext.lower() not in allowed:
            raise ValueError("unsupported image extension")
        path = self._case_dir(case_id) / f"original{ext.lower()}"
        path.write_bytes(image_bytes)
        return str(path)

    def save_case_record(self, case: CaseRecord) -> None:
        path = self._case_dir(case.case_id) / "prediction.json"
        path.write_text(case.model_dump_json(indent=2))

    def load_case_record(self, case_id: str) -> CaseRecord | None:
        path = self._case_dir(case_id) / "prediction.json"
        if not path.exists():
            return None
        return CaseRecord.model_validate_json(path.read_text())

    def save_reviews(self, case_id: str, reviews: list[ReviewedFinding]) -> None:
        path = self._case_dir(case_id) / "review.json"
        payload = [r.model_dump(mode="json") for r in reviews]
        path.write_text(json.dumps(payload, indent=2))

    def load_reviews(self, case_id: str) -> list[ReviewedFinding]:
        path = self._case_dir(case_id) / "review.json"
        if not path.exists():
            return []
        raw = json.loads(path.read_text())
        return [ReviewedFinding.model_validate(r) for r in raw]

    def case_exists(self, case_id: str) -> bool:
        try:
            d = self._case_dir(case_id)
        except ValueError:
            return False
        return (d / "prediction.json").exists()

    def list_cases(self) -> list[CaseRecord]:
        records = []
        for d in self.root.iterdir():
            if not d.is_dir():
                continue
            prediction_path = d / "prediction.json"
            if not prediction_path.exists():
                continue
            records.append(CaseRecord.model_validate_json(prediction_path.read_text()))
        return records

    def get_original_image_path(self, case_id: str) -> Path | None:
        d = self._case_dir(case_id)
        for match in d.glob("original.*"):
            return match
        return None

    def save_chat_history(self, case_id: str, messages: list[ChatMessage]) -> None:
        path = self._case_dir(case_id) / "chat.json"
        payload = [m.model_dump(mode="json") for m in messages]
        path.write_text(json.dumps(payload, indent=2))

    def load_chat_history(self, case_id: str) -> list[ChatMessage]:
        path = self._case_dir(case_id) / "chat.json"
        if not path.exists():
            return []
        raw = json.loads(path.read_text())
        return [ChatMessage.model_validate(m) for m in raw]

    def list_doctors(self) -> list[DoctorSummary]:
        counts: dict[str, int] = {}
        for record in self.list_cases():
            if not record.dentist_name:
                continue
            counts[record.dentist_name] = counts.get(record.dentist_name, 0) + 1
        return [
            DoctorSummary(doctor_id=name, name=name, case_count=count)
            for name, count in counts.items()
        ]

    def list_cases_for_doctor(self, doctor_id: str) -> list[CaseRecord]:
        return [r for r in self.list_cases() if r.dentist_name == doctor_id]

    def list_cases_for_patient(self, patient_id: str) -> list[CaseRecord]:
        return [r for r in self.list_cases() if r.patient_id == patient_id]
